const r = await tools.exec_command({cmd:"jq -r '.entries[] | select(.path=="content/workspace" or .path=="content/workspace/.git/annex/keysdb/db" or .path=="content/workspace/.git/annex/keysdb/db-shm" or .path=="content/workspace/.git/annex/keysdb/db-wal")' "$STAMPED_OPERATIONAL_MANIFEST" && cat > "$STAMPED_JUDGE_OUTPUT/operational-integrity-check.py" <<'PY'
import hashlib, json, os, pathlib, stat, sys
manifest_path = pathlib.Path(os.environ['STAMPED_OPERATIONAL_MANIFEST'])
root = pathlib.Path(os.environ['STAMPED_JUDGE_TARGET'])
manifest = json.loads(manifest_path.read_text())
expected = {}
for item in manifest['entries']:
    path = item['path']
    if path == 'content/workspace':
        rel = '.'
    elif path.startswith('content/workspace/'):
        rel = path[len('content/workspace/'):]
    else:
        continue
    expected[rel] = item
actual = set()
for here, dirs, files in os.walk(root, topdown=True, followlinks=False):
    base = pathlib.Path(here)
    names = dirs + files
    for name in names:
        p = base / name
        rel = p.relative_to(root).as_posix()
        actual.add(rel)
        st = p.lstat()
        exp = expected.get(rel)
        if exp is None:
            print('EXTRA', rel)
            continue
        mode = stat.S_IMODE(st.st_mode)
        if mode != exp.get('mode'):
            print('MODE', rel, exp.get('mode'), mode)
        if stat.S_ISLNK(st.st_mode):
            kind = 'symlink'
            target = os.readlink(p)
            if exp.get('kind') != kind or exp.get('link_target') != target:
                print('LINK', rel, exp.get('link_target'), target)
        elif stat.S_ISDIR(st.st_mode):
            if exp.get('kind') != 'directory':
                print('TYPE', rel, exp.get('kind'), 'directory')
        elif stat.S_ISREG(st.st_mode):
            if exp.get('kind') != 'file':
                print('TYPE', rel, exp.get('kind'), 'file')
                continue
            digest = hashlib.sha256(p.read_bytes()).hexdigest()
            if digest != exp.get('sha256'):
                label = 'OPERATIONAL_METADATA' if rel in {'.git/annex/keysdb/db', '.git/annex/keysdb/db-shm', '.git/annex/keysdb/db-wal'} else 'MISMATCH'
                print(label, rel, exp.get('sha256'), digest)
        else:
            print('TYPE', rel, exp.get('kind'), 'other')
for rel in sorted(set(expected) - actual):
    if rel != '.':
        print('MISSING', rel)
print(f'checked={len(actual)} expected={len(expected)}')
PY
